(()=>{'use strict';const el=id=>document.getElementById(id);
function review(){if(el('vlos').value!=='yes'&&el('scopeoption').value==='direct')el('scopeoption').value='unsupported';const mode=el('scopeoption').value;const reasons=[];if(el('vlos').value!=='yes'||mode==='unsupported')reasons.push('OUTSIDE SUPPORTED SCOPE: establish a supported VLOS plan; BVLOS and authorisation-specific assessment are not covered.');if(mode==='fpv'&&(!el('fpvconfirmed').checked||!el('fpvbasis').value.trim()))reasons.push('Record the adjacent FPV observer and briefing arrangement.');return{valid:reasons.length===0,mode,observer:mode==='fpv'?el('fpvbasis').value:'',confirmed:mode==='fpv'?el('fpvconfirmed').checked:null,reasons};}
window.flightScopeReview=review;
const controller=document.createElement('label');controller.className='check';controller.innerHTML='<input id="controllerready" type="checkbox"><span>Controller charge is adequate; control/link, firmware/geo-awareness and return/lost-link settings checked for this flight · GO/NO-GO required</span>';el('batteryconfirm').closest('label').before(controller);el('controllerready').addEventListener('change',()=>window.updateFlightdeskDecision?.());

function update(changed){const fpv=el('scopeoption').value==='fpv';el('fpvfields').hidden=!fpv;if(changed){el('vlos').value=el('scopeoption').value==='unsupported'?'no':'yes';el('finalconfirm').checked=false;}const r=review();el('scopestatus').textContent=r.valid?'Supported scope selected; assess VLOS in the final declaration.':r.reasons.join(' ');window.updateFlightdeskDecision?.();}
el('scopeoption').addEventListener('change',()=>update(true));el('fpvbasis').addEventListener('input',()=>{el('fpvconfirmed').checked=false;update(true);});el('fpvconfirmed').addEventListener('change',()=>update(true));
el('category').addEventListener('change',()=>{el('a2').closest('label').hidden=el('category').value!=='A2';});
const derived=[0,1,4,7,8];for(const i of derived){const c=el('check'+i);c.disabled=true;c.setAttribute('aria-label','Read-only summary from originating checks');c.closest('label').classList.add('derived-check');const p=document.createElement('p');p.className='hint';p.textContent='Read-only summary: complete the originating section; no second declaration is needed.';c.closest('.checkrow').querySelector('.checkdesc').append(p);}
let controllerSignature='';window.flightSyncEvidence=function(s){const nextControllerSignature=JSON.stringify([s.aircraft,el('assetidentity')?.value,el('payloadidentity')?.value,el('height').value,el('date').value,el('hour').value,el('startminute').value,el('batteryselect').value]);if(controllerSignature&&controllerSignature!==nextControllerSignature)el('controllerready').checked=false;controllerSignature=nextControllerSignature;const crew=(r,needed)=>!!r?.name&&(!needed||!!r.registration&&/^\d{4}-\d{2}-\d{2}$/.test(r.expiry||'')&&r.expiry>=s.date);const air=window.flightAirspaceReview?.();const flags={0:s.specConfirmed&&s.open&&!(s.reviewIssues||[]).length&&crew(s.pilot,s.flyerRequired)&&crew(s.operator,s.operatorRequired),1:!!air?.go,4:el('finalconfirm').checked&&review().valid&&(!el('vloslimituse').checked||el('vloslimitconfirm').checked),7:s.weatherAcknowledged&&s.coverage&&s.weatherAge!==null&&s.weatherAge<20&&(!s.onsite||s.onsite.valid),8:s.cellCheck&&s.batteryConfirmed&&s.battery?.health==='ready'&&el('controllerready').checked};for(const i of derived){const c=el('check'+i),was=c.checked;c.checked=!!flags[i];if(c.checked&&!was)el('checked'+i).textContent='Derived from originating checks · '+new Date().toISOString();if(!c.checked)el('checked'+i).textContent='';}el('a2').closest('label').hidden=el('category').value!=='A2';const n=Array.from(document.querySelectorAll('[data-check]')).filter(c=>c.checked).length;el('count').textContent=n+' / '+10+' recorded';el('progress').style.width=n/10*100+'%';};
update(false);
})();
